versions.variantCss:
.wemd-share-card[data-variant="bytedance-share-card"] {
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  padding: 20px 24px;
  margin: 16px 0;
  text-align: center;
  border: 1px dashed var(--wemd-border);
}
.wemd-share-card[data-variant="bytedance-share-card"] .wemd-component-body {
  padding: 0;
}
.wemd-share-card[data-variant="bytedance-share-card"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-text-strong);
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 6px 0;
}
.wemd-share-card[data-variant="bytedance-share-card"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0;
}
.wemd-share-card[data-variant="bytedance-share-card"] .wemd-component-body .wemd-child-3 {
  display: inline-block;
  background: var(--wemd-primary);
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  padding: 6px 16px;
  border-radius: 6px;
  margin: 8px 0 0 0;
}
